INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-a1-001',unit_id,topic_id,'Observando a imagem, que duas estruturas constituem o sistema nervoso central?','/quiz-images/neuro/aula-1/page-004-figure-2.jpeg','O sistema nervoso central é constituído pelo encéfalo e pela espinal medula. Os nervos cranianos e espinhais estabelecem a comunicação destas estruturas com a periferia.','easy','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_a1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=excluded.image_url,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
